window.ARENA_EXAMS.push({"roomId":String.raw`diali10-kntt-hk1-decuong`,"roomName":String.raw`Đề cương ôn tập Học kì 1 Địa Lí 10 (Kết nối tri thức)`,"type":String.raw`public`,"subject":String.raw`Địa lí`,"grade":10,"durationMinutes":90,"questions":[{"id":String.raw`C1`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`I. BẢN ĐỒ`,"q":String.raw`Để thể hiện các đối tượng phân bố theo những điểm cụ thể, người ta dùng phương pháp`,"a":[String.raw`kí hiệu đường chuyển động`,String.raw`kí hiệu`,String.raw`bản đồ - biểu đồ`,String.raw`chấm điểm`],"correct":1,"explain":String.raw`Phương pháp kí hiệu dùng để thể hiện các đối tượng địa lí phân bố theo những điểm cụ thể (đỉnh núi, mỏ khoáng sản,...). Chọn B.`},{"id":String.raw`C2`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`I. BẢN ĐỒ`,"q":String.raw`Để thể hiện hướng các loại gió, người ta dùng phương pháp`,"a":[String.raw`kí hiệu đường chuyển động`,String.raw`kí hiệu`,String.raw`bản đồ - biểu đồ`,String.raw`chấm điểm`],"correct":0,"explain":String.raw`Phương pháp kí hiệu đường chuyển động thể hiện sự di chuyển của các đối tượng, hiện tượng tự nhiên và kinh tế - xã hội (như hướng gió). Chọn A.`},{"id":String.raw`C3`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`I. BẢN ĐỒ`,"q":String.raw`Phương pháp khoanh vùng cho biết`,"a":[String.raw`vùng phân bố của đối tượng riêng lẻ.`,String.raw`số lượng của đối tượng riêng lẻ.`,String.raw`cơ cấu của đối tượng riêng lẻ.`,String.raw`tính phổ biến của đối tượng riêng lẻ.`],"correct":0,"explain":String.raw`Phương pháp khoanh vùng thể hiện vùng phân bố của các đối tượng riêng lẻ trên từng khu vực nhất định. Chọn A.`},{"id":String.raw`C4`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`I. BẢN ĐỒ`,"q":String.raw`GPS và bản đồ số không sử dụng trong lĩnh vực nào sau đây?`,"a":[String.raw`giao thông vận tải.`,String.raw`khí tượng và giám sát Trái Đất.`,String.raw`đo đạc khảo sát công trình.`,String.raw`nghiên cứu cấu trúc Trái Đất.`],"correct":3,"explain":String.raw`GPS và bản đồ số được ứng dụng trong giao thông, khí tượng, khảo sát công trình,... không dùng để nghiên cứu cấu trúc bên trong Trái Đất. Chọn D.`},{"id":String.raw`C5`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`I. BẢN ĐỒ`,"q":String.raw`Phương pháp chấm điểm không thể hiện được đặc tính nào sau đây của đối tượng?`,"a":[String.raw`Cơ cấu.`,String.raw`Sự phân bố.`,String.raw`Số lượng.`,String.raw`Chất lượng.`],"correct":3,"explain":String.raw`Phương pháp chấm điểm chủ yếu thể hiện sự phân bố và số lượng (mỗi chấm tương ứng một giá trị nhất định), không thể hiện chất lượng. Chọn D.`},{"id":String.raw`C6a`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`II. TRÁI ĐẤT`,"q":String.raw`Điểm nào sau đây không phải là nguyên nhân dẫn đến hiện tượng ngày và đêm luân phiên xuất hiện trên Trái Đất?`,"a":[String.raw`Trái Đất hình cầu.`,String.raw`Trái Đất tự quay mình theo chiều từ tây sang đông.`,String.raw`Trái Đất chuyển động xung quanh Mặt Trời.`,String.raw`Trục Trái Đất luôn nghiêng một góc 66°33'.`],"correct":2,"explain":String.raw`Ngày đêm luân phiên là hệ quả của hình dạng cầu và chuyển động tự quay quanh trục của Trái Đất, không phải do quay quanh Mặt Trời. Chọn C.`},{"id":String.raw`C6b`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`II. TRÁI ĐẤT`,"q":String.raw`Nơi nào sau đây trong năm luôn có thời gian ngày và đêm dài bằng nhau?`,"a":[String.raw`Chí tuyến.`,String.raw`Vòng cực.`,String.raw`Cực.`,String.raw`Xích đạo.`],"correct":3,"explain":String.raw`Ở Xích đạo, đường phân chia sáng tối luôn chia đôi vĩ tuyến nên ngày và đêm quanh năm dài bằng nhau (12 giờ). Chọn D.`},{"id":String.raw`C6c`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`II. TRÁI ĐẤT`,"q":String.raw`Việt Nam (nằm ở múi giờ số 7) muộn hơn Nhật Bản (nằm ở múi giờ số 9) là`,"a":[String.raw`1 giờ.`,String.raw`2 giờ.`,String.raw`3 giờ.`,String.raw`4 giờ.`],"correct":1,"explain":String.raw`Nhật Bản ở múi giờ 9, Việt Nam ở múi giờ 7 nên Việt Nam muộn hơn 9 - 7 = 2 giờ. Chọn B.`},{"id":String.raw`C6d`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`II. TRÁI ĐẤT`,"q":String.raw`Phát biểu nào sau đây không đúng với hiện tượng mùa trên Trái Đất?`,"a":[String.raw`Mùa là một phần thời gian của năm.`,String.raw`Đặc điểm khí hậu các mùa khác nhau.`,String.raw`Do Trái Đất tự quay quanh trục gây ra.`,String.raw`Các mùa có lượng bức xạ khác nhau.`],"correct":2,"explain":String.raw`Mùa sinh ra do Trái Đất chuyển động quanh Mặt Trời với trục nghiêng không đổi phương, không phải do tự quay quanh trục. Chọn C.`},{"id":String.raw`C6e`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`II. TRÁI ĐẤT`,"q":String.raw`Về mùa hạ, các địa điểm trên bán cầu Bắc luôn có`,"a":[String.raw`ngày dài hơn đêm.`,String.raw`đêm dài hơn ngày.`,String.raw`ngày đêm bằng nhau.`,String.raw`toàn ngày hoặc đêm.`],"correct":0,"explain":String.raw`Mùa hạ bán cầu Bắc ngả về phía Mặt Trời nên có thời gian chiếu sáng lớn, ngày dài hơn đêm. Chọn A.`},{"id":String.raw`C6f`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`II. TRÁI ĐẤT`,"q":String.raw`Kinh tuyến được chọn để làm đường chuyển ngày quốc tế là`,"a":[String.raw`90°.`,String.raw`120°.`,String.raw`150°.`,String.raw`180°.`],"correct":3,"explain":String.raw`Kinh tuyến 180° đi qua giữa múi giờ số 12 ở Thái Bình Dương được chọn làm đường chuyển ngày quốc tế. Chọn D.`},{"id":String.raw`C7`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`III. THẠCH QUYỂN`,"q":String.raw`Vật liệu cấu tạo nên vỏ Trái Đất là`,"a":[String.raw`khoáng vật và đá trầm tích.`,String.raw`đá mac-ma và biến chất.`,String.raw`đất và khoáng vật.`,String.raw`khoáng vật và đá.`],"correct":3,"explain":String.raw`Vật liệu cấu tạo nên vỏ Trái Đất là khoáng vật và các loại đá. Chọn D.`},{"id":String.raw`C8`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`III. THẠCH QUYỂN`,"q":String.raw`Nơi tiếp xúc giữa các mảng kiến tạo thường xuất hiện`,"a":[String.raw`động đất, núi lửa.`,String.raw`bão.`,String.raw`ngập lụt.`,String.raw`thủy triều dâng.`],"correct":0,"explain":String.raw`Vùng tiếp xúc các mảng kiến tạo là vùng bất ổn của vỏ Trái Đất, thường xảy ra động đất, núi lửa. Chọn A.`},{"id":String.raw`C9`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`III. THẠCH QUYỂN`,"q":String.raw`Các mảng kiến tạo có thể di chuyển là do`,"a":[String.raw`Trái Đất bị nghiêng và quay quanh Mặt Trời.`,String.raw`Trái Đất luôn tự quay quanh trục của chính nó.`,String.raw`các dòng đối lưu vật chất quánh dẻo của manti trên.`,String.raw`sức hút mạnh mẽ từ các thiên thể mà nhiều nhất là Mặt Trời.`],"correct":2,"explain":String.raw`Các mảng kiến tạo dịch chuyển nhờ hoạt động của các dòng đối lưu vật chất quánh dẻo trong lớp manti trên. Chọn C.`},{"id":String.raw`C10`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`III. THẠCH QUYỂN`,"q":String.raw`Thạch quyển gồm`,"a":[String.raw`vỏ Trái Đất và phần trên cùng của lớp Man-ti.`,String.raw`phần trên cùng của lớp Man-ti và đá trầm tích.`,String.raw`đá badan và phần ở trên cùng của lớp Man-ti.`,String.raw`phần trên cùng của lớp Man-ti và đá biến chất.`],"correct":0,"explain":String.raw`Thạch quyển bao gồm toàn bộ vỏ Trái Đất và phần cứng mỏng phía trên cùng của lớp Man-ti. Chọn A.`},{"id":String.raw`C11`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`III. THẠCH QUYỂN`,"q":String.raw`Vận động nào sau đây không do tác động của nội lực?`,"a":[String.raw`Uốn nếp.`,String.raw`Bóc mòn.`,String.raw`Đứt gãy.`,String.raw`Nâng lên hạ xuống.`],"correct":1,"explain":String.raw`Bóc mòn là quá trình do ngoại lực gây ra; uốn nếp, đứt gãy, nâng lên hạ xuống thuộc nội lực. Chọn B.`},{"id":String.raw`C12`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`III. THẠCH QUYỂN`,"q":String.raw`Hiện tượng vỏ Trái Đất bị nén ép ở khu vực này và tách giãn ở khu vực khác xảy ra do chịu tác động của`,"a":[String.raw`hiện tượng uốn nếp.`,String.raw`hiện tượng đứt gãy.`,String.raw`vận động theo phương thẳng đứng.`,String.raw`vận động theo phương nằm ngang.`],"correct":3,"explain":String.raw`Vận động theo phương nằm ngang làm vỏ Trái Đất bị nén ép ở nơi này, tách giãn ở nơi khác (sinh ra uốn nếp, đứt gãy). Chọn D.`},{"id":String.raw`C13`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`III. THẠCH QUYỂN`,"q":String.raw`Các cồn cát ven biển là kết quả trực tiếp của quá trình`,"a":[String.raw`phong hoá.`,String.raw`vận chuyển.`,String.raw`bồi tụ.`,String.raw`bóc mòn.`],"correct":2,"explain":String.raw`Các cồn cát ven biển hình thành trực tiếp do quá trình bồi tụ của gió và sóng biển. Chọn C.`},{"id":String.raw`C14`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`IV. KHÍ QUYỂN`,"q":String.raw`Thành phần chính trong không khí là khí`,"a":[String.raw`Nitơ.`,String.raw`Ôxi.`,String.raw`Cacbonic.`,String.raw`Hơi nước.`],"correct":0,"explain":String.raw`Không khí gồm khoảng 78,1% nitơ, 20,9% ôxi và 1% các khí khác -> thành phần chính là Nitơ. Chọn A.`},{"id":String.raw`C15`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`IV. KHÍ QUYỂN`,"q":String.raw`Biên độ nhiệt trong năm theo vĩ độ có đặc điểm`,"a":[String.raw`tăng dần từ xích đạo về cực.`,String.raw`giảm dần từ chí tuyến về hai phía.`,String.raw`giảm dần từ xích đạo về cực.`,String.raw`không có sự thay đổi nhiều.`],"correct":0,"explain":String.raw`Càng lên vĩ độ cao, chênh lệch góc nhập xạ và thời gian chiếu sáng giữa các mùa càng lớn nên biên độ nhiệt năm tăng dần từ xích đạo về cực. Chọn A.`},{"id":String.raw`C16`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`IV. KHÍ QUYỂN`,"q":String.raw`Các khu áp thấp thường là nơi có lượng mưa`,"a":[String.raw`lớn.`,String.raw`nhỏ.`,String.raw`trung bình.`,String.raw`rất nhỏ.`],"correct":0,"explain":String.raw`Khu áp thấp hút gió và đẩy không khí ẩm lên cao, ngưng tụ tạo mây gây mưa lớn. Chọn A.`},{"id":String.raw`C17`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`IV. KHÍ QUYỂN`,"q":String.raw`Khu vực nào có lượng mưa nhiều nhất trên bề mặt Trái Đất?`,"a":[String.raw`vùng xích đạo.`,String.raw`vùng chí tuyến.`,String.raw`vùng ôn đới.`,String.raw`vùng cực.`],"correct":0,"explain":String.raw`Vùng xích đạo có áp thấp thường xuyên, dải hội tụ nhiệt đới, nhiệt độ cao, mưa đối lưu lớn nên mưa nhiều nhất Trái Đất. Chọn A.`},{"id":String.raw`C18`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`IV. KHÍ QUYỂN`,"q":String.raw`Các khu áp cao thường có mưa rất ít hoặc không có mưa là do`,"a":[String.raw`có ít gió thổi đến, độ ẩm không khí rất thấp.`,String.raw`nằm sâu trong lục địa, độ ẩm không khí rất thấp.`,String.raw`chỉ có không khí khô bốc lên cao, độ ẩm rất thấp.`,String.raw`không khí ẩm không bốc lên được lại chỉ có gió thổi đi.`],"correct":3,"explain":String.raw`Ở khu áp cao, không khí giáng xuống nên ẩm không bốc lên được và chỉ có gió thổi đi, vì thế ít mưa. Chọn D.`},{"id":String.raw`C19`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`IV. KHÍ QUYỂN`,"q":String.raw`Khu vực áp cao chí tuyến thường có hoang mạc lớn do không khí`,"a":[String.raw`nóng.`,String.raw`lạnh.`,String.raw`khô.`,String.raw`ẩm.`],"correct":2,"explain":String.raw`Dưới áp cao cận chí tuyến, không khí khô, ít mưa nên hình thành nhiều hoang mạc lớn. Chọn C.`},{"id":String.raw`C20`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`IV. KHÍ QUYỂN`,"q":String.raw`Vùng chí tuyến có mưa tương đối ít, chủ yếu là do`,"a":[String.raw`các khu khí áp cao hoạt động quanh năm.`,String.raw`các dòng biển lạnh ở cả hai bờ đại dương.`,String.raw`có gió thường xuyên và gió mùa thổi đến.`,String.raw`có nhiều khu vực địa hình núi cao đồ sộ.`],"correct":0,"explain":String.raw`Vùng chí tuyến chịu sự thống trị quanh năm của áp cao cận chí tuyến và gió Mậu dịch khô nên ít mưa. Chọn A.`},{"id":String.raw`C21`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`IV. KHÍ QUYỂN`,"q":String.raw`Các nhân tố làm cho vùng xích đạo có mưa rất nhiều là`,"a":[String.raw`áp thấp, dải hội tụ nhiệt đới, dòng biển nóng.`,String.raw`áp thấp, dải hội tụ nhiệt đới, dòng biển lạnh.`,String.raw`dải hội tụ nhiệt đới, frông nóng, gió Mậu dịch.`,String.raw`dải hội tụ nhiệt đới, các núi cao, gió Mậu dịch.`],"correct":0,"explain":String.raw`Vùng xích đạo mưa rất nhiều nhờ áp thấp xích đạo, dải hội tụ nhiệt đới và các dòng biển nóng. Chọn A.`},{"id":String.raw`C22`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`“Toàn bộ lớp nước bao quanh Trái Đất, phân bố trong các đại dương, trên lục địa, trong các lớp đất đá, trong khí quyển và cơ thể sinh vật” được gọi là`,"a":[String.raw`khí quyển.`,String.raw`thạch quyển.`,String.raw`sinh quyển.`,String.raw`thủy quyển.`],"correct":3,"explain":String.raw`Đó là khái niệm của thủy quyển. Chọn D.`},{"id":String.raw`C23`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`“Là dòng chảy thường xuyên, tương đối lớn trên lục địa và đảo” được gọi là`,"a":[String.raw`sông.`,String.raw`suối.`,String.raw`hồ.`,String.raw`dòng biển.`],"correct":0,"explain":String.raw`Sông là dòng chảy thường xuyên, tương đối lớn trên bề mặt lục địa và đảo. Chọn A.`},{"id":String.raw`C24`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Chế độ nước sông phụ thuộc chủ yếu vào`,"a":[String.raw`nguồn cấp nước và bề mặt lưu vực`,String.raw`nguồn cấp nước và địa hình`,String.raw`bề mặt lưu vực và nước mưa`,String.raw`nước mưa hay băng tuyết tan`],"correct":0,"explain":String.raw`Chế độ nước sông chịu ảnh hưởng chủ yếu của nguồn cung cấp nước và đặc điểm bề mặt lưu vực. Chọn A.`},{"id":String.raw`C25`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Nhân tố nào sau đây có vai trò điều tiết dòng chảy?`,"a":[String.raw`Nước mưa`,String.raw`Băng tuyết tan`,String.raw`Hồ, đầm`,String.raw`Địa hình`],"correct":2,"explain":String.raw`Hồ, đầm giữ bớt nước khi sông dâng lũ và bổ sung nước khi sông cạn nên có vai trò điều tiết dòng chảy. Chọn C.`},{"id":String.raw`C26`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Nguồn cung cấp nước chính cho sông là`,"a":[String.raw`nước mưa hay băng tuyết tan`,String.raw`nước mưa hay hồ đầm`,String.raw`băng tuyết tan hay địa hình`,String.raw`nước mưa hay các phụ lưu sông.`],"correct":0,"explain":String.raw`Nguồn cung cấp nước chính cho sông là nước mưa và nước băng tuyết tan. Chọn A.`},{"id":String.raw`C27`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Nhân tố nào sau đây ít ảnh hưởng đến chế độ nước sông?`,"a":[String.raw`Chế độ mưa.`,String.raw`Băng tuyết.`,String.raw`Địa hình.`,String.raw`Dòng biển.`],"correct":3,"explain":String.raw`Dòng biển ít ảnh hưởng trực tiếp đến chế độ nước sông trên lục địa. Chọn D.`},{"id":String.raw`C28`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`“Là những vùng trũng chứa nước trên bề mặt Trái Đất, không trực tiếp thông với biển” được gọi là`,"a":[String.raw`sông.`,String.raw`suối.`,String.raw`hồ.`,String.raw`dòng biển.`],"correct":2,"explain":String.raw`Đó là khái niệm của hồ. Chọn C.`},{"id":String.raw`C29`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Hồ Bai-can (Liên Bang Nga) thuộc loại hồ nào?`,"a":[String.raw`Hồ băng hà.`,String.raw`Hồ kiến tạo.`,String.raw`Hồ nhân tạo.`,String.raw`Hồ miệng núi lửa.`],"correct":1,"explain":String.raw`Hồ Bai-can là hồ kiến tạo, hình thành tại vùng sụt lún kiến tạo sâu. Chọn B.`},{"id":String.raw`C30`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Phân loại hồ theo nguồn gốc hình thành, có các loại`,"a":[String.raw`hồ băng hà và hồ nhân tạo.`,String.raw`hồ tự nhiên và hồ nhân tạo.`,String.raw`hồ tự nhiên và hồ móng ngựa.`,String.raw`hồ băng hà và hồ miệng núi lửa.`],"correct":1,"explain":String.raw`Theo nguồn gốc hình thành, hồ chia thành hai nhóm lớn: hồ tự nhiên và hồ nhân tạo. Chọn B.`},{"id":String.raw`C31`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Nước trên lục địa gồm nước ở`,"a":[String.raw`trên mặt, nước ngầm.`,String.raw`trên mặt, hơi nước.`,String.raw`nước ngầm, hơi nước.`,String.raw`băng tuyết, sông, hồ.`],"correct":0,"explain":String.raw`Nước trên lục địa gồm nước trên mặt (sông, hồ, băng tuyết) và nước ngầm. Chọn A.`},{"id":String.raw`C32`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Băng và tuyết là nước ở thể nào sau đây?`,"a":[String.raw`Rắn.`,String.raw`Lỏng.`,String.raw`Hơi.`,String.raw`Khí.`],"correct":0,"explain":String.raw`Băng và tuyết là nước ở trạng thái đóng băng (thể rắn). Chọn A.`},{"id":String.raw`C33`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Hồ thủy điện Hòa Bình trên sông Đà nước ta thuộc loại hồ nào sau đây?`,"a":[String.raw`Hồ băng hà.`,String.raw`Hồ tự nhiên.`,String.raw`Hồ nhân tạo.`,String.raw`Hồ miệng núi lửa.`],"correct":2,"explain":String.raw`Hồ thủy điện Hòa Bình do con người xây đập ngăn sông tạo thành nên là hồ nhân tạo. Chọn C.`},{"id":String.raw`C34`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Hồ Tây (Hà Nội) thuộc loại hồ nào sau đây?`,"a":[String.raw`Hồ băng hà.`,String.raw`Hồ tự nhiên.`,String.raw`Hồ móng ngựa.`,String.raw`Hồ miệng núi lửa.`],"correct":2,"explain":String.raw`Hồ Tây hình thành từ một khúc uốn cũ của sông Hồng bị tách khỏi dòng chính -> hồ móng ngựa. Chọn C.`},{"id":String.raw`C35`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Nước băng tuyết phổ biến ở vùng`,"a":[String.raw`nhiệt đới, hàn đới, trên núi cao.`,String.raw`hàn đới, ôn đới, trên núi cao.`,String.raw`nhiệt đới, ôn đới, trên núi cao.`,String.raw`xích đạo, nhiệt đới, trên núi cao.`],"correct":1,"explain":String.raw`Băng tuyết phổ biến ở những nơi nhiệt độ thấp: vùng hàn đới, ôn đới và trên các vùng núi cao. Chọn B.`},{"id":String.raw`C36`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Chế độ mưa ảnh hưởng tới chế độ nước sông là`,"a":[String.raw`điều tiết chế độ dòng chảy sông.`,String.raw`quy định chế độ dòng chảy sông.`,String.raw`tăng rất nhanh lưu lượng dòng chảy.`,String.raw`quy định tốc độ dòng chảy sông.`],"correct":1,"explain":String.raw`Chế độ mưa quy định chế độ dòng chảy sông (mùa mưa trùng mùa lũ, mùa khô trùng mùa cạn). Chọn B.`},{"id":String.raw`C37`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Ở miền ôn đới lạnh, sông thường lũ lụt vào mùa nào trong năm?`,"a":[String.raw`Mùa hạ.`,String.raw`Mùa đông.`,String.raw`Mùa xuân.`,String.raw`Mùa thu.`],"correct":2,"explain":String.raw`Ở miền ôn đới lạnh, vào mùa xuân nhiệt độ ấm lên làm băng tuyết tan mạnh khiến sông có lũ lớn. Chọn C.`},{"id":String.raw`C38`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Băng hà có tác dụng chính trong việc`,"a":[String.raw`dự trữ nguồn nước ngọt.`,String.raw`điều hoà khí hậu.`,String.raw`hạ thấp mực nước biển.`,String.raw`nâng độ cao địa hình.`],"correct":0,"explain":String.raw`Băng hà là kho dự trữ nước ngọt lớn nhất trên Trái Đất. Chọn A.`},{"id":String.raw`C39`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Sông ngòi ở vùng khí hậu nóng hoặc những nơi địa hình thấp của khí hậu ôn đới thì nguồn cung nước chủ yếu là`,"a":[String.raw`nước mưa.`,String.raw`băng tuyết.`,String.raw`nước ngầm.`,String.raw`các hồ chứa.`],"correct":0,"explain":String.raw`Ở vùng khí hậu nóng và vùng địa hình thấp ôn đới, nguồn cấp nước chủ yếu cho sông là nước mưa. Chọn A.`},{"id":String.raw`C40`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Tác động tiêu cực của con người đến chế độ nước sông là`,"a":[String.raw`xây dựng công trình thủy lợi.`,String.raw`phá rừng đầu nguồn.`,String.raw`trồng và bảo vệ rừng.`,String.raw`xây dựng hồ chứa thủy điện.`],"correct":1,"explain":String.raw`Phá rừng đầu nguồn làm mất lớp phủ giữ nước, khiến lũ lên nhanh và mùa cạn kiệt nước. Chọn B.`},{"id":String.raw`C41`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Phần lớn lượng nước ngầm trên lục địa có nguồn gốc từ`,"a":[String.raw`nước trên mặt đất thấm xuống.`,String.raw`nước từ biển, đại dương thấm vào.`,String.raw`nước từ dưới lớp vỏ Trái Đất ngấm ngược lên.`,String.raw`khi hình thành Trái Đất nước ngầm đã xuất hiện.`],"correct":0,"explain":String.raw`Nước ngầm chủ yếu do nước trên mặt (mưa, băng tuyết tan, sông, hồ) thấm xuống lòng đất. Chọn A.`},{"id":String.raw`C42`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Ở miền khí hậu nóng, nhân tố chủ yếu tác động đến chế độ nước sông là`,"a":[String.raw`nước ngầm.`,String.raw`chế độ mưa.`,String.raw`địa hình.`,String.raw`thực vật.`],"correct":1,"explain":String.raw`Ở miền khí hậu nóng, nguồn cung nước chính cho sông là nước mưa nên chế độ nước phụ thuộc chủ yếu vào chế độ mưa. Chọn B.`},{"id":String.raw`C43`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Ý nghĩa của hồ đầm đối với sông là`,"a":[String.raw`điều hoà chế độ nước sông.`,String.raw`nhiều thung lũng.`,String.raw`giảm lưu lượng nước sông.`,String.raw`địa hình dốc.`],"correct":0,"explain":String.raw`Hồ đầm giúp điều hòa chế độ nước sông giữa mùa lũ và mùa cạn. Chọn A.`},{"id":String.raw`C44`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Sông nào sau đây chảy qua Việt Nam?`,"a":[String.raw`Nin.`,String.raw`I-ê-nit-xây.`,String.raw`A-ma-dôn.`,String.raw`Mê Công.`],"correct":3,"explain":String.raw`Sông Mê Công chảy qua lãnh thổ Việt Nam (đổ ra biển Đông qua hệ thống sông Cửu Long). Chọn D.`},{"id":String.raw`C45`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Giải pháp nào sau đây không nhằm bảo vệ nguồn nước ngọt?`,"a":[String.raw`Chống ô nhiễm và giữ sạch nguồn nước.`,String.raw`Sử dụng lãng phí, gây ô nhiễm nguồn nước.`,String.raw`Tuyên truyền, nâng cao ý thức sử dụng và bảo vệ.`,String.raw`Đẩy mạnh trồng rừng và bảo vệ tốt rừng đầu nguồn.`],"correct":1,"explain":String.raw`Sử dụng lãng phí, gây ô nhiễm là hành động phá hoại nguồn nước ngọt. Chọn B.`},{"id":String.raw`C46`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. THỦY QUYỂN`,"q":String.raw`Việc phá hoại rừng phòng hộ ở thượng nguồn sông sẽ dẫn tới hậu quả là`,"a":[String.raw`mực nước sông quanh năm thấp, sông chảy chậm chạp.`,String.raw`mực nước sông quanh năm cao, sông chảy xiết.`,String.raw`mùa lũ nước sông dâng cao đột ngột, mùa cạn mực nước cạn kiệt.`,String.raw`sông sẽ không còn nước, chảy quanh co uốn khúc.`],"correct":2,"explain":String.raw`Mất rừng phòng hộ đầu nguồn làm giảm khả năng giữ nước, gây lũ quét đột ngột mùa mưa và cạn kiệt mùa khô. Chọn C.`},{"id":String.raw`C47`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Độ muối trung bình của nước biển là`,"a":[String.raw`33‰.`,String.raw`34‰.`,String.raw`35‰.`,String.raw`36‰.`],"correct":2,"explain":String.raw`Độ muối trung bình của nước biển và đại dương là 35‰. Chọn C.`},{"id":String.raw`C48`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Nhiệt độ trung bình của nước biển và đại dương là`,"a":[String.raw`17°C.`,String.raw`34°C.`,String.raw`35°C.`,String.raw`18°C.`],"correct":0,"explain":String.raw`Nhiệt độ trung bình của nước biển và đại dương thế giới khoảng 17°C. Chọn A.`},{"id":String.raw`C49`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Độ muối nước biển lớn nhất ở vùng`,"a":[String.raw`xích đạo.`,String.raw`chí tuyến.`,String.raw`cực.`,String.raw`ôn đới.`],"correct":1,"explain":String.raw`Vùng chí tuyến có độ bốc hơi rất lớn, ít mưa và ít sông lớn đổ ra nên độ muối cao nhất (~36,8‰). Chọn B.`},{"id":String.raw`C50`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Nguyên nhân chủ yếu hình thành sóng là do`,"a":[String.raw`nước chảy.`,String.raw`gió thổi.`,String.raw`băng tan.`,String.raw`mưa rơi.`],"correct":1,"explain":String.raw`Nguyên nhân chủ yếu sinh ra sóng biển là gió thổi. Chọn B.`},{"id":String.raw`C51`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Các dòng biển nóng thường hình thành ở khu vực nào của Trái Đất?`,"a":[String.raw`Xích đạo.`,String.raw`Chí tuyến.`,String.raw`Ôn đới.`,String.raw`Vùng cực.`],"correct":0,"explain":String.raw`Dòng biển nóng thường phát sinh ở hai bên Xích đạo rồi chảy về phía vĩ độ cao. Chọn A.`},{"id":String.raw`C52`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Các dòng biển lạnh thường xuất phát từ`,"a":[String.raw`vùng vĩ độ cao về vĩ độ thấp`,String.raw`vùng vĩ độ thấp về vĩ độ cao`,String.raw`bờ đông sang bờ tây đại dương`,String.raw`cực về vùng xích đạo`],"correct":0,"explain":String.raw`Dòng biển lạnh thường xuất phát từ vùng vĩ độ cao chảy về vùng vĩ độ thấp. Chọn A.`},{"id":String.raw`C53`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Thủy triều là hiện tượng dao động thường xuyên và có chu kì của các khối nước trong`,"a":[String.raw`các dòng sông lớn.`,String.raw`các ao hồ.`,String.raw`các đầm lầy.`,String.raw`các biển và đại dương.`],"correct":3,"explain":String.raw`Thủy triều là dao động thường xuyên, có chu kì của các khối nước trong các biển và đại dương. Chọn D.`},{"id":String.raw`C54`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Khi Mặt Trăng, Mặt Trời và Trái Đất ở vị trí như thế nào thì dao động của thủy triều nhỏ nhất?`,"a":[String.raw`Thẳng hàng.`,String.raw`Vòng cung.`,String.raw`Đối xứng.`,String.raw`Vuông góc.`],"correct":3,"explain":String.raw`Khi ba thiên thể nằm vuông góc, lực hút triệt tiêu một phần nên dao động thủy triều nhỏ nhất (triều kém). Chọn D.`},{"id":String.raw`C55`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Khi Mặt Trăng, Mặt Trời và Trái Đất ở vị trí như thế nào thì dao động của thủy triều lớn nhất?`,"a":[String.raw`Thẳng hàng.`,String.raw`Vòng cung.`,String.raw`Đối xứng.`,String.raw`Vuông góc.`],"correct":0,"explain":String.raw`Khi Mặt Trăng, Mặt Trời và Trái Đất thẳng hàng, lực hút cộng hưởng nên dao động thủy triều lớn nhất (triều cường). Chọn A.`},{"id":String.raw`C56`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Thủy triều hình thành do`,"a":[String.raw`sức hút của dải ngân hà.`,String.raw`sức hút của các hành tinh.`,String.raw`sức hút của các thiên thạch.`,String.raw`sức hút của Mặt Trăng, Mặt Trời.`],"correct":3,"explain":String.raw`Thủy triều hình thành chủ yếu do sức hút của Mặt Trăng và Mặt Trời. Chọn D.`},{"id":String.raw`C57`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Sóng biển là`,"a":[String.raw`hình thức dao động của nước biển theo chiều thẳng đứng.`,String.raw`sự chuyển động của nước biển từ ngoài khơi xô vào bờ.`,String.raw`hình thức dao động của nước biển theo chiều ngang.`,String.raw`sự di chuyển của nước biển theo các hướng khác nhau.`],"correct":0,"explain":String.raw`Sóng biển là hình thức dao động của nước biển theo chiều thẳng đứng. Chọn A.`},{"id":String.raw`C58`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Khi Mặt Trời, Mặt Trăng, Trái Đất nằm thẳng hàng thì dao động thủy triều`,"a":[String.raw`không đáng kể.`,String.raw`nhỏ nhất.`,String.raw`trung bình.`,String.raw`lớn nhất.`],"correct":3,"explain":String.raw`Khi ba thiên thể nằm thẳng hàng thì dao động thủy triều lớn nhất (triều cường). Chọn D.`},{"id":String.raw`C59`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Nguyên nhân chủ yếu tạo nên sóng biển là`,"a":[String.raw`dòng biển.`,String.raw`gió thổi.`,String.raw`động đất.`,String.raw`núi lửa.`],"correct":1,"explain":String.raw`Gió thổi là nguyên nhân chủ yếu sinh ra sóng biển; gió càng mạnh sóng càng lớn. Chọn B.`},{"id":String.raw`C60`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Hình thức dao động của sóng biển là theo chiều`,"a":[String.raw`thẳng đứng.`,String.raw`xoay tròn.`,String.raw`chiều ngang.`,String.raw`xô vào bờ.`],"correct":0,"explain":String.raw`Sóng biển dao động theo chiều thẳng đứng. Chọn A.`},{"id":String.raw`C61`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Nguyên nhân gây ra sóng thần chủ yếu là`,"a":[String.raw`gió.`,String.raw`bão.`,String.raw`động đất.`,String.raw`núi lửa.`],"correct":2,"explain":String.raw`Sóng thần chủ yếu do động đất ngầm dưới đáy biển gây ra. Chọn C.`},{"id":String.raw`C62`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Nhiệt độ trung bình của đại dương thế giới là`,"a":[String.raw`15,5°C.`,String.raw`16,5°C.`,String.raw`17,5°C.`,String.raw`18,5°C.`],"correct":2,"explain":String.raw`Theo SGK Địa lí 10 KNTT, nhiệt độ trung bình bề mặt của đại dương thế giới khoảng 17,5°C. Chọn C.`},{"id":String.raw`C63`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Phát biểu nào sau đây đúng về sự thay đổi nhiệt độ nước biển theo thời gian?`,"a":[String.raw`Mùa đông có nhiệt độ cao hơn mùa thu.`,String.raw`Ban ngày có nhiệt độ thấp hơn ban đêm.`,String.raw`Ban trưa có nhiệt độ thấp hơn ban chiều.`,String.raw`Mùa hạ có nhiệt độ cao hơn mùa đông.`],"correct":3,"explain":String.raw`Nhiệt độ nước biển thay đổi theo mùa: mùa hạ cao hơn mùa đông. Chọn D.`},{"id":String.raw`C64`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Độ muối của nước biển không phụ thuộc vào`,"a":[String.raw`lượng mưa.`,String.raw`lượng bốc hơi.`,String.raw`lượng nước ở các hồ đầm.`,String.raw`lượng nước sông chảy ra.`],"correct":2,"explain":String.raw`Độ muối nước biển phụ thuộc vào tương quan giữa lượng bốc hơi, lượng mưa và lượng nước sông đổ ra, không phụ thuộc hồ đầm nội địa. Chọn C.`},{"id":String.raw`C65`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Nhiệt độ của nước biển và đại dương`,"a":[String.raw`giảm dần từ vùng cực về xích đạo.`,String.raw`cao nhất ở vùng cận nhiệt và ôn đới.`,String.raw`thay đổi theo vĩ độ và theo độ sâu.`,String.raw`từ độ sâu 300m trở lên rất ít thay đổi.`],"correct":2,"explain":String.raw`Nhiệt độ nước biển và đại dương thay đổi theo vĩ độ, theo mùa và giảm dần theo độ sâu. Chọn C.`},{"id":String.raw`C66`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Độ muối của nước biển và đại dương`,"a":[String.raw`giảm dần từ vùng cực về xích đạo.`,String.raw`các đại dương độ muối nhỏ hơn ven biển.`,String.raw`có sự thay đổi theo không gian và theo mùa.`,String.raw`khu vực xích đạo có độ muối lớn nhất.`],"correct":2,"explain":String.raw`Độ muối nước biển thay đổi theo không gian (vĩ độ, ven bờ - ngoài khơi) và theo mùa. Chọn C.`},{"id":String.raw`C67`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Càng xuống sâu, nhiệt độ nước biển càng`,"a":[String.raw`thấp.`,String.raw`cao.`,String.raw`tăng.`,String.raw`không thay đổi.`],"correct":0,"explain":String.raw`Càng xuống sâu bức xạ mặt trời càng giảm nên nhiệt độ nước biển càng thấp. Chọn A.`},{"id":String.raw`C68`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Nhiệt độ nước biển phụ thuộc vào nhiệt độ của`,"a":[String.raw`không khí.`,String.raw`đất liền.`,String.raw`đáy biển.`,String.raw`bờ biển.`],"correct":0,"explain":String.raw`Nhiệt độ nước biển tầng mặt phụ thuộc trực tiếp vào chế độ nhiệt của không khí và bức xạ Mặt Trời. Chọn A.`},{"id":String.raw`C69`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Sử dụng thủy triều không nhằm mục đích chủ yếu nào sau đây?`,"a":[String.raw`Giao thông vận tải.`,String.raw`Nuôi trồng thủy sản.`,String.raw`Sản xuất điện năng.`,String.raw`Giảm thiểu hạn hán.`],"correct":3,"explain":String.raw`Thủy triều giúp phát triển giao thông biển, nuôi trồng thủy sản, làm muối, điện thủy triều; không dùng để giảm hạn hán. Chọn D.`},{"id":String.raw`C70`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Ở vùng gió mùa thường xuất hiện các dòng biển`,"a":[String.raw`thay đổi nhiệt độ theo mùa.`,String.raw`thay đổi độ ẩm theo mùa.`,String.raw`thay đổi chiều theo mùa.`,String.raw`thay đổi tốc độ theo mùa.`],"correct":2,"explain":String.raw`Ở khu vực gió mùa (như Ấn Độ Dương, Biển Đông), các dòng biển thường đổi chiều theo mùa gió. Chọn C.`},{"id":String.raw`C71`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`V. NƯỚC BIỂN VÀ ĐẠI DƯƠNG`,"q":String.raw`Phát biểu nào sau đây không đúng về vai trò của biển và đại dương đối với sự phát triển kinh tế - xã hội?`,"a":[String.raw`Cung cấp tài nguyên sinh vật biển.`,String.raw`Cung cấp tài nguyên khoáng sản biển.`,String.raw`Thuận lợi phát triển nền nông nghiệp.`,String.raw`Phát triển các ngành kinh tế biển.`],"correct":2,"explain":String.raw`Biển và đại dương cung cấp sinh vật, khoáng sản và phát triển kinh tế biển, không phải điều kiện trực tiếp để phát triển nền nông nghiệp trồng trọt. Chọn C.`},{"id":String.raw`C72`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Đặc trưng của đất (thổ nhưỡng) là`,"a":[String.raw`tơi xốp.`,String.raw`độ phì.`,String.raw`độ ẩm.`,String.raw`vụn bở.`],"correct":1,"explain":String.raw`Đặc trưng cơ bản nhất của đất là độ phì. Chọn B.`},{"id":String.raw`C73`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Lớp vật chất mỏng bao phủ bề mặt các lục địa và đảo, được tạo thành do quá trình phong hóa các loại đá được gọi là`,"a":[String.raw`Khí quyển.`,String.raw`Sinh quyển.`,String.raw`Thủy quyển.`,String.raw`Đất.`],"correct":3,"explain":String.raw`Đó là định nghĩa của đất (thổ nhưỡng). Chọn D.`},{"id":String.raw`C74`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Sinh quyển là một trong những bộ phận cấu tạo của Trái Đất, nơi có`,"a":[String.raw`sự sống tồn tại.`,String.raw`tất cả sinh vật và thổ nhưỡng.`,String.raw`toàn bộ động vật và vi sinh vật.`,String.raw`toàn bộ thực vật và vi sinh vật.`],"correct":0,"explain":String.raw`Sinh quyển là toàn bộ không gian trên Trái Đất nơi có sự sống tồn tại. Chọn A.`},{"id":String.raw`C75`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Nhân tố nào sau đây có tác động đến việc tạo nên thành phần hữu cơ cho đất?`,"a":[String.raw`Khí hậu.`,String.raw`Sinh vật.`,String.raw`Địa hình.`,String.raw`Đá mẹ.`],"correct":1,"explain":String.raw`Sinh vật cung cấp xác hữu cơ và phân giải chất hữu cơ tạo mùn cho đất. Chọn B.`},{"id":String.raw`C76`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Khí hậu ảnh hưởng trực tiếp đến quá trình hình thành đất thông qua`,"a":[String.raw`độ ẩm và lượng mưa.`,String.raw`lượng bức xạ và lượng mưa.`,String.raw`nhiệt độ và lượng mưa.`,String.raw`nhiệt độ và nắng.`],"correct":2,"explain":String.raw`Nhiệt độ và lượng mưa của khí hậu tác động trực tiếp tới tốc độ phong hóa đá và rửa trôi/tích tụ trong đất. Chọn C.`},{"id":String.raw`C77`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Nhân tố quyết định đến sự phát triển và phân bố của động vật là`,"a":[String.raw`địa hình.`,String.raw`nguồn nước.`,String.raw`nguồn thức ăn.`,String.raw`đất.`],"correct":2,"explain":String.raw`Nguồn thức ăn (gắn với thảm thực vật) là nhân tố quyết định sự phân bố và phát triển của động vật. Chọn C.`},{"id":String.raw`C78`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Loài cây ưa nhiệt thường phân bố ở vùng`,"a":[String.raw`ôn đới, nhiệt đới.`,String.raw`nhiệt đới, cận nhiệt.`,String.raw`nhiệt đới, xích đạo.`,String.raw`cận nhiệt, ôn đới.`],"correct":2,"explain":String.raw`Vùng nhiệt đới và xích đạo có nền nhiệt độ cao, dồi dào nên thích hợp với các loài cây ưa nhiệt. Chọn C.`},{"id":String.raw`C79`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Đất được hình thành do tác động đồng thời của các nhân tố`,"a":[String.raw`đá mẹ, khí hậu, sinh vật, địa hình, con người.`,String.raw`khí hậu, đất, sinh vật, địa hình, con người.`,String.raw`đá mẹ, sông ngòi, sinh vật, địa hình, con người.`,String.raw`khí hậu, sinh vật, địa hình, con người, khoáng sản.`],"correct":0,"explain":String.raw`Các nhân tố hình thành đất gồm: đá mẹ, khí hậu, sinh vật, địa hình, thời gian và con người. Chọn A.`},{"id":String.raw`C80`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Tác động quan trọng nhất của sinh vật đối với việc hình thành đất là`,"a":[String.raw`làm đá gốc bị phá huỷ.`,String.raw`cung cấp chất hữu cơ.`,String.raw`cung cấp chất vô cơ.`,String.raw`tạo các vành đai đất.`],"correct":1,"explain":String.raw`Vai trò quan trọng nhất của sinh vật là cung cấp và tổng hợp chất hữu cơ (độ phì) cho đất. Chọn B.`},{"id":String.raw`C81`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Lớp phủ thực vật có tác dụng như thế nào đến sự hình thành đất?`,"a":[String.raw`Hạn chế xói mòn đất.`,String.raw`Phá hủy đá gốc.`,String.raw`Tích tụ vật chất.`,String.raw`Phân giải chất hữu cơ.`],"correct":0,"explain":String.raw`Lớp phủ thực vật giúp giữ ẩm và hạn chế xói mòn, rửa trôi đất. Chọn A.`},{"id":String.raw`C82`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Hoạt động nào sau đây của con người không làm biến đổi tính chất của đất?`,"a":[String.raw`Nông nghiệp.`,String.raw`Lâm nghiệp.`,String.raw`Ngư nghiệp.`,String.raw`Công nghiệp.`],"correct":2,"explain":String.raw`Ngư nghiệp (đánh bắt, nuôi trồng thủy sản trên biển/mặt nước) không trực tiếp làm biến đổi tính chất đất như nông, lâm, công nghiệp. Chọn C.`},{"id":String.raw`C83`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Độ cao ảnh hưởng tới sự phân bố vành đai thực vật thông qua`,"a":[String.raw`nhiệt độ và độ ẩm.`,String.raw`độ ẩm và lượng mưa.`,String.raw`lượng mưa và gió.`,String.raw`độ ẩm và khí áp.`],"correct":0,"explain":String.raw`Càng lên cao nhiệt độ và độ ẩm thay đổi tạo nên các vành đai thực vật theo độ cao. Chọn A.`},{"id":String.raw`C84`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Phát biểu nào sau đây đúng với ảnh hưởng của đất tới sự phát triển và phân bố của sinh vật?`,"a":[String.raw`Mỗi loài cây thích nghi với một giới hạn nhiệt nhất định.`,String.raw`Thực vật sinh trưởng nhờ đặc tính lí, hoá, độ phì của đất.`,String.raw`Sinh vật phát triển tốt trong môi trường tốt về nhiệt, ẩm.`,String.raw`Cây xanh nhờ ánh sáng để thực hiện quá trình quang hợp.`],"correct":1,"explain":String.raw`Các đặc tính lí, hóa và độ phì của đất ảnh hưởng trực tiếp tới sự sinh trưởng và phân bố thực vật. Chọn B.`},{"id":String.raw`C85`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Ảnh hưởng tích cực của con người đối với sự phân bố sinh vật không phải là`,"a":[String.raw`giảm diện tích rừng tự nhiên, mất nơi ở động vật.`,String.raw`thay đổi phạm vi phân bố của nhiều loại cây trồng.`,String.raw`đưa động vật nuôi từ lục địa này sang lục địa khác.`,String.raw`trồng rừng, mở rộng diện tích rừng ở toàn thế giới.`],"correct":0,"explain":String.raw`Làm giảm diện tích rừng tự nhiên, mất nơi ở động vật là tác động tiêu cực. Chọn A.`},{"id":String.raw`C86`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Tác động chủ yếu của con người đối với sự phân bố sinh vật là`,"a":[String.raw`thu hẹp diện tích rừng trên bề mặt Trái Đất.`,String.raw`thay đổi phạm vi phân bố của cây trồng, vật nuôi.`,String.raw`làm tuyệt chủng một số loài động vật, thực vật hoang dã.`,String.raw`tạo ra một số loài động, thực vật mới trong quá trình lai tạo.`],"correct":1,"explain":String.raw`Con người tác động chủ yếu thông qua việc mở rộng, thay đổi phạm vi phân bố của cây trồng và vật nuôi. Chọn B.`},{"id":String.raw`C87`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Cho biểu đồ lưu lượng nước trung bình tháng của sông Hồng tại trạm Hà Nội. Nhận xét nào sau đây đúng?`,"a":[String.raw`Mùa lũ từ tháng 6 đến tháng 10`,String.raw`Mùa lũ từ tháng 11 đến tháng 5 năm sau`,String.raw`Mùa cạn từ tháng 6 đến tháng 10`,String.raw`Mùa cạn từ tháng 1 đến tháng 5`],"correct":0,"explain":String.raw`Các tháng có lưu lượng lớn hơn trung bình năm (3262,6 m³/s) là từ tháng 6 đến tháng 10 -> mùa lũ từ tháng 6 đến tháng 10. Chọn A.`,"image":String.raw`data:image/webp;base64,`},{"id":String.raw`C88`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Quan sát bảng 13 (SGK/44). Để thể hiện lưu lượng nước trung bình tháng của sông Hồng tại trạm Hà Nội, biểu đồ thích hợp nhất là`,"a":[String.raw`cột`,String.raw`tròn`,String.raw`đường`,String.raw`kết hợp`],"correct":2,"explain":String.raw`Biểu đồ đường thích hợp nhất để thể hiện diễn biến lưu lượng nước sông liên tục qua 12 tháng trong năm. Chọn C.`},{"id":String.raw`C89`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Quan sát hình 10.2 (SGK/36), cho biết nhận xét nào sau đây không đúng với biểu đồ nhiệt độ, lượng mưa của Hà Nội và U-pha?`,"a":[String.raw`Hà Nội mưa nhiều từ tháng 5 đến tháng 10.`,String.raw`U-pha có tổng lượng mưa ít hơn Hà Nội.`,String.raw`Hà Nội có biên độ nhiệt năm nhỏ hơn U-pha.`,String.raw`Mùa đông ở U-pha nhiệt độ thấp hơn ở Hà Nội.`],"correct":2,"explain":String.raw`Theo đáp án của đề cương chọn C (lưu ý thực tế trên biểu đồ SGK, Hà Nội có biên độ nhiệt năm ~12°C, nhỏ hơn U-pha). Chọn C.`},{"id":String.raw`C90`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Cho bảng số liệu: <b>Nhiệt độ và độ muối của các đại dương trên thế giới</b><div style='overflow-x:auto;margin:10px 0;'><table style='border-collapse:collapse;width:100%;font-size:14px;background:#ffffff;border:1px solid #94a3b8;'><thead><tr><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Đại dương</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Độ muối (‰)</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Nhiệt độ (°C)</th></tr></thead><tbody><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Thái Bình Dương</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>34,9</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>19,1</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Đại Tây Dương</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>35,5</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>16,9</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Ấn Độ Dương</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>34,8</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>17,0</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Bắc Băng Dương</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>31,0</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>0,75</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Đại dương thế giới</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>35,0</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>17,0</td></tr></tbody></table></div>Để thể hiện độ muối và nhiệt độ của các đại dương trên thế giới, biểu đồ thích hợp nhất là`,"a":[String.raw`tròn`,String.raw`miền`,String.raw`đường`,String.raw`cột`],"correct":3,"explain":String.raw`Biểu đồ cột (cột kép) thích hợp nhất để so sánh hai chỉ tiêu độ muối và nhiệt độ giữa các đại dương. Chọn D.`},{"id":String.raw`C91`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Từ bảng số liệu câu 90 (nhiệt độ và độ muối các đại dương), nhận xét nào sau đây không đúng?`,"a":[String.raw`Phần lớn các đại dương có độ muối thấp hơn độ muối trung bình của đại dương thế giới.`,String.raw`Bắc Băng Dương có độ muối và nhiệt độ thấp hơn trung bình các đại dương thế giới.`,String.raw`Thái Bình Dương có độ muối thấp hơn nhưng nhiệt độ cao hơn trung bình các đại dương thế giới.`,String.raw`Thái Bình Dương có độ muối và nhiệt độ cao hơn trung bình các đại dương thế giới.`],"correct":3,"explain":String.raw`Thái Bình Dương có nhiệt độ (19,1°C) cao hơn trung bình (17,0°C) nhưng độ muối (34,9‰) thấp hơn trung bình (35,0‰). Chọn D.`},{"id":String.raw`C92`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Theo bảng số liệu: <b>Sự thay đổi của biên độ nhiệt độ năm theo vĩ độ địa lí trên Trái Đất (°C)</b><div style='overflow-x:auto;margin:10px 0;'><table style='border-collapse:collapse;width:100%;font-size:14px;background:#ffffff;border:1px solid #94a3b8;'><thead><tr><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Vĩ độ</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>0°</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>20°</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>30°</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>40°</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>50°</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>60°</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>70°</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>80°</th></tr></thead><tbody><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Bán cầu Bắc</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>1,8</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>7,4</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>13,3</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>17,7</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>23,8</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>29,0</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>32,2</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>31,0</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Bán cầu Nam</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>1,8</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>5,9</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>7,0</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>4,9</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>4,3</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>11,8</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>19,5</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>28,7</td></tr></tbody></table></div>Nhận xét nào sau đây đúng về thay đổi biên độ nhiệt độ năm theo vĩ độ địa lí?`,"a":[String.raw`Càng lên vĩ độ cao, biên độ nhiệt độ năm càng tăng.`,String.raw`Càng về ở xích đạo, biên độ nhiệt độ năm càng tăng.`,String.raw`Biên độ nhiệt năm ở các vĩ độ bán cầu Bắc nhỏ hơn bán cầu Nam.`,String.raw`Biên độ nhiệt năm ở vĩ độ thấp lớn hơn ở vĩ độ cao.`],"correct":0,"explain":String.raw`Từ 0° đến 70°–80°, xu hướng chung là càng lên vĩ độ cao biên độ nhiệt độ năm càng tăng. Chọn A.`},{"id":String.raw`C93`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`<b>Nhiệt độ trung bình tháng của Hà Nội năm 2020 (°C):</b><div style='overflow-x:auto;margin:10px 0;'><table style='border-collapse:collapse;width:100%;font-size:14px;background:#ffffff;border:1px solid #94a3b8;'><thead><tr><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Tháng</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>1</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>2</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>3</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>4</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>5</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>6</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>7</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>8</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>9</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>10</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>11</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>12</th></tr></thead><tbody><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Hà Nội</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>16,4</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>17,0</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>20,2</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>23,7</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>27,3</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>28,8</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>28,9</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>28,2</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>27,2</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>24,6</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>21,4</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>18,2</td></tr></tbody></table></div>Dựa vào bảng số liệu, hãy tính biên độ nhiệt của Hà Nội năm 2020?`,"a":[String.raw`12,5°C`,String.raw`12,4°C`,String.raw`11,9°C`,String.raw`1,25°C`],"correct":0,"explain":String.raw`Biên độ nhiệt năm = Tmax (tháng 7: 28,9°C) - Tmin (tháng 1: 16,4°C) = 12,5°C. Chọn A.`},{"id":String.raw`C94`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Cho bảng số liệu: <b>Một số chỉ số về nhiệt độ của Hà Nội và TP. Hồ Chí Minh (°C)</b><div style='overflow-x:auto;margin:10px 0;'><table style='border-collapse:collapse;width:100%;font-size:14px;background:#ffffff;border:1px solid #94a3b8;'><thead><tr><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Địa điểm</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Nhiệt độ TB năm (°C)</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Biên độ nhiệt TB năm (°C)</th></tr></thead><tbody><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Hà Nội</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>23,5</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>12,5</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>TP. Hồ Chí Minh</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>27,5</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>3,1</td></tr></tbody></table></div>Nhận định nào sau đây là không đúng với bảng số liệu trên?`,"a":[String.raw`Nhiệt độ trung bình năm Hà Nội thấp hơn TP. Hồ Chí Minh`,String.raw`Biên độ nhiệt độ trung bình năm TP. Hồ Chí Minh thấp hơn Hà Nội`,String.raw`Nhiệt độ trung bình năm giảm dần từ Hà Nội vào TP.HCM`,String.raw`Biên độ nhiệt trung bình năm giảm dần từ Hà Nội vào TP.HCM`],"correct":2,"explain":String.raw`Nhiệt độ trung bình năm tăng từ Hà Nội (23,5°C) vào TP.HCM (27,5°C), không phải giảm dần. Chọn C.`},{"id":String.raw`C95`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Cho bảng số liệu: <b>Nhiệt độ trung bình tháng 1 tại một số địa điểm (°C)</b><div style='overflow-x:auto;margin:10px 0;'><table style='border-collapse:collapse;width:100%;font-size:14px;background:#ffffff;border:1px solid #94a3b8;'><thead><tr><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Địa điểm</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Lạng Sơn</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Hà Nội</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Vinh</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Huế</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Quy Nhơn</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>TP. Hồ Chí Minh</th></tr></thead><tbody><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Nhiệt độ TB tháng 1 (°C)</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>13,3</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>16,4</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>17,6</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>19,7</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>23,0</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>25,8</td></tr></tbody></table></div>Biểu đồ thích hợp nhất thể hiện nhiệt độ trung bình tháng 1 tại một số địa điểm trên ở nước ta là`,"a":[String.raw`miền.`,String.raw`cột.`,String.raw`tròn.`,String.raw`kết hợp.`],"correct":1,"explain":String.raw`Biểu đồ cột thích hợp nhất để so sánh giá trị nhiệt độ giữa các địa điểm khác nhau. Chọn B.`},{"id":String.raw`C96`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Cho bảng số liệu: <b>Nhiệt độ trung bình tại một số địa điểm (°C)</b><div style='overflow-x:auto;margin:10px 0;'><table style='border-collapse:collapse;width:100%;font-size:14px;background:#ffffff;border:1px solid #94a3b8;'><thead><tr><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>Địa điểm</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>TB tháng 1 (°C)</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>TB tháng 7 (°C)</th><th style='border:1px solid #94a3b8;padding:6px 10px;background:#f1f5f9;font-weight:700;text-align:center;'>TB năm (°C)</th></tr></thead><tbody><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Lạng Sơn</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>13,3</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>27,0</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>21,2</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Hà Nội</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>16,4</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>28,9</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>23,5</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Vinh</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>17,6</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>29,6</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>23,9</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Huế</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>19,7</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>29,4</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>25,1</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>Quy Nhơn</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>23,0</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>29,7</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>26,8</td></tr><tr><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:left;font-weight:600;'>TP. Hồ Chí Minh</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>25,8</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>27,1</td><td style='border:1px solid #94a3b8;padding:6px 10px;text-align:center;'>27,1</td></tr></tbody></table></div>Nhận xét nào sau đây không đúng với bảng số liệu trên?`,"a":[String.raw`Nhiệt độ trung bình tháng 1 tăng dần từ Bắc vào Nam.`,String.raw`Nhiệt độ trung bình năm tăng dần từ Bắc vào Nam.`,String.raw`Càng vào Nam, biên độ nhiệt trung bình năm càng chênh lệch lớn.`,String.raw`Nhiệt độ trung bình tháng 7 không chênh lệch nhiều giữa các địa điểm.`],"correct":2,"explain":String.raw`Càng vào Nam biên độ nhiệt năm càng nhỏ (Lạng Sơn 13,7°C -> TP.HCM 1,3°C). Chọn C.`},{"id":String.raw`C97`,"type":String.raw`single`,"subject":String.raw`geography`,"section":String.raw`VI. SINH QUYỂN & KĨ NĂNG ĐỊA LÍ`,"q":String.raw`Từ bảng số liệu câu 96, hãy cho biết biên độ nhiệt độ năm của Hà Nội là (°C)`,"a":[String.raw`18,1.`,String.raw`19,9.`,String.raw`12,5.`,String.raw`13,1.`],"correct":2,"explain":String.raw`Biên độ nhiệt độ năm của Hà Nội = 28,9 - 16,4 = 12,5°C. Chọn C.`},{"id":String.raw`B1`,"type":String.raw`essay`,"subject":String.raw`geography`,"section":String.raw`PHẦN TỰ LUẬN`,"q":String.raw`Trình bày các giải pháp chủ yếu để bảo vệ nguồn nước ngọt? Là học sinh, em cần làm những việc gì để bảo vệ nguồn nước ngọt?`,"correct":String.raw`Giáo viên chấm`,"explain":String.raw`<b>a. Giải pháp chủ yếu:</b> Quản lí và sử dụng tiết kiệm, hiệu quả nguồn nước; xây dựng hệ thống xử lí nước thải trước khi xả ra môi trường; bảo vệ rừng đầu nguồn và hệ sinh thái tự nhiên; giáo dục, nâng cao ý thức cộng đồng.<br><b>b. Việc làm của học sinh:</b> Tiết kiệm nước sinh hoạt hằng ngày; không xả rác, chất thải xuống sông hồ; trồng và bảo vệ cây xanh; tích cực tuyên truyền, tham gia bảo vệ môi trường nước.`},{"id":String.raw`B2`,"type":String.raw`essay`,"subject":String.raw`geography`,"section":String.raw`PHẦN TỰ LUẬN`,"q":String.raw`Trình bày các nhân tố ảnh hưởng đến chế độ nước sông?`,"correct":String.raw`Giáo viên chấm`,"explain":String.raw`• <b>Chế độ mưa & băng tuyết tan (nguồn cấp nước):</b> Quy định lưu lượng và sự phân mùa lũ – cạn của sông.<br>• <b>Địa hình:</b> Độ dốc và hướng sườn quyết định tốc độ dòng chảy và tốc độ tập trung lũ.<br>• <b>Hồ, đầm & thực vật:</b> Giữ nước, làm chậm dòng chảy, điều hòa chế độ nước sông.<br>• <b>Hoạt động của con người:</b> Xây dựng hồ chứa thủy điện, công trình thủy lợi, trồng hoặc phá rừng đầu nguồn.`},{"id":String.raw`B3`,"type":String.raw`essay`,"subject":String.raw`geography`,"section":String.raw`PHẦN TỰ LUẬN`,"q":String.raw`Kể tên các nhân tố ảnh hưởng đến độ muối và nhiệt độ của nước biển và đại dương.`,"correct":String.raw`Giáo viên chấm`,"explain":String.raw`• <b>Nhân tố ảnh hưởng đến độ muối:</b> Lượng nước bốc hơi, lượng mưa và lượng nước ngọt từ sông, băng tan đổ vào.<br>• <b>Nhân tố ảnh hưởng đến nhiệt độ nước biển:</b> Vĩ độ địa lí, mùa trong năm, độ sâu mực nước và tác động của các dòng biển.`},{"id":String.raw`B4`,"type":String.raw`essay`,"subject":String.raw`geography`,"section":String.raw`PHẦN TỰ LUẬN`,"q":String.raw`Trình bày vai trò của nước biển và đại dương.`,"correct":String.raw`Giáo viên chấm`,"explain":String.raw`• <b>Điều hòa khí hậu:</b> Hấp thụ và phân phối nhiệt, cung cấp độ ẩm cho khí quyển.<br>• <b>Tài nguyên thiên nhiên:</b> Cung cấp nguồn lợi sinh vật biển, dầu khí, khoáng sản và năng lượng (sóng, thủy triều, gió biển).<br>• <b>Kinh tế - xã hội:</b> Phát triển giao thông vận tải biển, du lịch biển, nuôi trồng – đánh bắt thủy sản và cung cấp nguồn nước khử mặn.`},{"id":String.raw`B5`,"type":String.raw`essay`,"subject":String.raw`geography`,"section":String.raw`PHẦN TỰ LUẬN`,"q":String.raw`Đà Nẵng đã tận dụng lợi thế của biển để phát triển những ngành kinh tế nào?`,"correct":String.raw`Giáo viên chấm`,"explain":String.raw`• <b>Du lịch biển:</b> Bãi biển Mỹ Khê, bán đảo Sơn Trà, hệ thống khu nghỉ dưỡng ven biển.<br>• <b>Kinh tế cảng biển & logistics:</b> Phát triển cảng Tiên Sa, cảng Liên Chiểu và vận tải biển.<br>• <b>Thủy sản:</b> Đánh bắt xa bờ, nuôi trồng và chế biến xuất khẩu thủy hải sản.<br>• <b>Công nghiệp & năng lượng biển:</b> Đóng tàu, chế biến hải sản, khai thác tài nguyên và năng lượng gió biển.`}]});
